  &DefaultButton;




function dir$dmloaibencang(p){
  this.constructor(p);
}
dir$dmloaibencang.prototype = new DirEvent();
dir$dmloaibencang.prototype.afterInit = function(){
  var p = this._dir;
}
dir$dmloaibencang.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid()

  dir$dmloaibencangDisabledMasterField(p, g);

}

function dir$dmloaibencangDisabledMasterField(p, g){

  if(p.valForm('ma_loai').trim() != '')
  {
    p.setDisabled('ma_loai', true);
  }
  else
  {
    p.setDisabled('ma_loai', false);
  }
}








declare @codeExistsNewMsg nvarchar(256), @codeExistsEditMsg nvarchar(256)
select @codeExistsNewMsg = case when '@@lan' = 'v' then N'Mã loại bến cảng đã tồn tại' else N'Port type code already exists' end
select @codeExistsEditMsg = case when '@@lan' = 'v' then N'Mã loại bến cảng đã tồn tại' else N'Port type code already exists' end
